def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    opp_d = sum(1 for m in opp_moves if m == 'D')
    my_d = sum(1 for m in my_moves if m == 'D')
    opp_c = n - opp_d

    last_my = my_moves[-1]
    last_opp = opp_moves[-1]

    # Recent windows
    w10 = opp_moves[-10:] if n >= 10 else opp_moves
    w5 = opp_moves[-5:] if n >= 5 else opp_moves
    r10_d = sum(1 for m in w10 if m == 'D')
    r5_c = sum(1 for m in w5 if m == 'C')

    # Consecutive opponent defections
    consec_d = 0
    for m in reversed(opp_moves):
        if m == 'D':
            consec_d += 1
        else:
            break

    # Consecutive opponent cooperations
    consec_c = 0
    for m in reversed(opp_moves):
        if m == 'C':
            consec_c += 1
        else:
            break

    # Consecutive our defections
    my_consec_d = 0
    for m in reversed(my_moves):
        if m == 'D':
            my_consec_d += 1
        else:
            break

    # Detect always-defect opponent (not just early noise)
    if n >= 6 and opp_d >= n - 1:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Detect all-defect after retaliation window
    if n >= 8 and opp_d == n:
        if n % 17 == 0:
            return 'C'
        return 'D'

    remaining = 100 - n

    # Endgame
    if remaining <= 1:
        # Last round: defect unless opponent nearly always defects (then D anyway)
        return 'D'

    if remaining <= 3:
        # If opponent is highly cooperative, exploit
        if opp_d <= max(1, n // 8):
            return 'D'
        if last_opp == 'D' or consec_d >= 2:
            return 'D'
        return 'C'

    if remaining <= 6:
        if opp_d * 3 <= n:
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        if consec_d >= 2:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Opponent is heavily defecting overall: switch to defection, sparse probes
    if n >= 8 and opp_d >= (n * 3) // 5:
        if n % 11 == 0:
            return 'C'
        return 'D'

    # Opponent mostly cooperative overall: cooperate, occasional controlled probe
    # to test whether they punish. Only probe when we've been cooperating.
    if n >= 8 and opp_c * 4 >= n * 3:
        # Punish an isolated recent defection by them briefly
        if consec_d == 1:
            return 'D'
        if consec_d >= 2:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Probe sparingly when our record is clean
        if my_consec_d == 0 and n > 20 and n % 9 == 0 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Opponent moderately defecting. Tit-for-tat-with-forgiveness core.
    if last_opp == 'D':
        if consec_d >= 3:
            # Long defection streak: punish harder, sparse forgiveness
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if consec_d == 2:
            # If recent they still show some cooperation, forgive
            if r5_c >= 2 and rng.random() < 0.4:
                return 'C'
            return 'D'
        # consec_d == 1
        # Isolated defection: retaliate once, but if overall more cooperative, forgive
        if opp_c * 2 >= n and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if my_consec_d >= 2:
        # We've been punishing; return to cooperation to signal willingness
        return 'C'
    if my_consec_d == 1:
        # We defected; cooperate back
        return 'C'
    # Probe occasionally when safe and mid-match
    if n > 25 and remaining > 15 and n % 12 == 0 and rng.random() < 0.25:
        return 'D'
    return 'C'
